context_info = ()
for d in context:
    prompt = "You are given a single document. Extract any information relevant to identifying a specific video game that matches ALL of the following clues, if present:\n- Released between 2001 and 2007.\n- Story premise includes: a woman is found dead; the player partners with another character to investigate.\n- Gameplay has two distinct phases: one centered on discovery of details (e.g., investigation/examination) and another centered on confrontation (e.g., interrogation/courtroom/prosecution/cross-examination).\n- Developed by a company established in 1998, known for producing its own award-winning, character-focused content.\n- Published by a company that was previously known by a different name and served as the parent company for two other game studios.\n\nFrom the document, list any potential matches for the game, the developer, and the publisher. If any of the parts (game/dev/publisher) are mentioned, include them even if the doc does not contain all parts. For each candidate, provide:\n- Game title and release year if given\n- Developer name and founding year if given\n- Publisher name and its former name if given, and which studios it parented\n- Verbatim supporting quotes from the document (short, only the needed lines)\nIf nothing relevant appears, output NONE.\n\nBEGIN_DOCUMENT\n" + d + "\nEND_DOCUMENT"
    result = llm_query(prompt)
    context_info = context_info + (result,)

combined = "\n\n----\n\n".join(context_info)

final_prompt = "We are trying to identify a single video game described by these constraints:\n- Released between 2001 and 2007.\n- A woman is found dead, and the player partners with another character to investigate.\n- Gameplay features two distinct phases: one focused on discovery of details and another on confrontation (e.g., interrogation/courtroom/prosecution/cross-examination).\n- Developed by a company established in 1998 that is known for producing its own award-winning, character-focused content.\n- The publisher was previously known by a different name and served as the parent company for two other gaming studios.\n\nBelow are extractions from our context documents that may include the game, developer, and publisher details:\n\n" + combined + "\n\nBased on this information only, identify the single best-matching game and output ONLY its exact title, with no additional words or punctuation."
answer = llm_query(final_prompt)
return_result(answer)